"use client";

import { useState } from "react";
import { ArrowDownWideNarrow, ArrowUpNarrowWide, Table2 } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { Card } from "@/components/ui/card";
import { IssueProperty } from "./issue-property-menu";
import { cn } from "@/lib/utils";
import {
  issuePriorities,
  useTrackerIssues,
  type TrackerProps,
} from "./tracker-issues";

export function IssueTable({
  title = "Реестр задач",
  className,
  ...props
}: TrackerProps & { title?: string }) {
  const { rows, update } = useTrackerIssues(props);
  const [order, setOrder] = useState<"descending" | "ascending">("descending");
  const [edit, setEdit] = useState<{ id: string; text: string } | null>(null);
  const reduce = useReducedMotion();
  const ordered = [...rows].sort(
    (a, b) =>
      (issuePriorities.indexOf(a.priority) -
        issuePriorities.indexOf(b.priority)) *
      (order === "descending" ? 1 : -1),
  );
  const SortIcon =
    order === "descending" ? ArrowDownWideNarrow : ArrowUpNarrowWide;
  function finish(
    id: string,
    value: string,
    restoreFocus: boolean,
    input: HTMLInputElement,
  ) {
    const cell = input.closest("td");
    const text = value.trim();
    if (text && rows.find((row) => row.id === id)?.title !== text)
      update(id, { title: text });
    setEdit(null);
    if (restoreFocus)
      requestAnimationFrame(() =>
        cell?.querySelector("button")?.focus({ preventScroll: true }),
      );
  }
  return (
    <Card className={cn("w-full min-w-0 gap-0 p-0 text-left", className)}>
      <header className="flex items-center gap-2 border-b px-3 py-3">
        <Table2 size={16} />
        <h3 className="flex-1 text-sm font-semibold">{title}</h3>
        <span className="font-mono text-xs text-muted-foreground">
          {rows.length}
        </span>
      </header>
      <div className="max-h-80 overflow-auto">
        <table className="w-full table-fixed border-collapse text-left text-xs">
          <thead className="sticky top-0 z-10 bg-muted">
            <tr className="text-[10px] text-muted-foreground">
              <th scope="col" className="px-2 py-2 font-medium">
                Задача
              </th>
              <th scope="col" className="w-[29%] px-1 font-medium">
                Статус
              </th>
              <th
                scope="col"
                aria-sort={order}
                className="w-[30%] px-1 font-medium"
              >
                <button
                  type="button"
                  aria-label="Сортировать по приоритету"
                  onClick={() =>
                    setOrder(
                      order === "descending" ? "ascending" : "descending",
                    )
                  }
                  className="inline-flex items-center gap-0.5 rounded py-2"
                >
                  Приоритет
                  <SortIcon size={11} />
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {ordered.map((issue) => (
              <motion.tr
                layout={reduce ? false : "position"}
                transition={{ type: "spring", stiffness: 365, damping: 34 }}
                key={issue.id}
                className="border-t hover:bg-muted/35"
              >
                <td className="px-2 py-2 align-middle">
                  <span className="block font-mono text-[9px] text-muted-foreground">
                    {issue.id}
                  </span>
                  {edit?.id === issue.id ? (
                    <input
                      autoFocus
                      aria-label="Название задачи"
                      className="w-full min-w-0 rounded border bg-background p-1 text-xs"
                      value={edit.text}
                      onFocus={(event) => event.currentTarget.select()}
                      onChange={(e) =>
                        setEdit({ id: issue.id, text: e.target.value })
                      }
                      onBlur={(e) =>
                        finish(
                          issue.id,
                          e.currentTarget.value,
                          false,
                          e.currentTarget,
                        )
                      }
                      onKeyDown={(e) => {
                        if (e.nativeEvent.isComposing) return;
                        if (e.key === "Enter" || e.key === "Escape") {
                          e.preventDefault();
                          finish(
                            issue.id,
                            e.key === "Enter" ? e.currentTarget.value : "",
                            true,
                            e.currentTarget,
                          );
                        }
                      }}
                    />
                  ) : (
                    <button
                      type="button"
                      aria-label={"Переименовать " + issue.title}
                      onClick={() =>
                        setEdit({ id: issue.id, text: issue.title })
                      }
                      className="block min-h-6 max-w-full rounded text-left text-xs leading-tight font-medium wrap-anywhere"
                    >
                      {issue.title}
                    </button>
                  )}
                </td>
                <td className="px-0.5">
                  <IssueProperty
                    issue={issue}
                    field="status"
                    onChange={(status) => update(issue.id, { status })}
                  />
                </td>
                <td className="px-0.5">
                  <IssueProperty
                    issue={issue}
                    field="priority"
                    onChange={(priority) => update(issue.id, { priority })}
                  />
                </td>
              </motion.tr>
            ))}
          </tbody>
        </table>
        {rows.length === 0 && (
          <p className="p-5 text-center text-xs text-muted-foreground">
            Пока нет задач
          </p>
        )}
      </div>
    </Card>
  );
}

"use client";

import { useState } from "react";
export const issueStatuses = ["backlog", "active", "done"] as const;
export const issuePriorities = ["high", "medium", "low"] as const;
export type IssueStatus = (typeof issueStatuses)[number];
export type IssuePriority = (typeof issuePriorities)[number];
export type TrackerIssue = {
  id: string;
  title: string;
  status: IssueStatus;
  priority: IssuePriority;
  points: number;
  cycleId?: string;
};
export type TrackerProps = {
  issues?: TrackerIssue[];
  defaultIssues?: TrackerIssue[];
  onIssuesChange?: (issues: TrackerIssue[]) => void;
  className?: string;
};

export const statusNames = {
  backlog: "Очередь",
  active: "В работе",
  done: "Готово",
};
export const priorityNames = {
  high: "Высокий",
  medium: "Средний",
  low: "Низкий",
};
const example: TrackerIssue[] = [
  {
    id: "LAB-24",
    title: "Поиск по урокам",
    status: "backlog",
    priority: "high",
    points: 5,
  },
  {
    id: "LAB-23",
    title: "Черновики решений",
    status: "active",
    priority: "high",
    points: 3,
    cycleId: "08",
  },
  {
    id: "LAB-22",
    title: "Разбор ошибок",
    status: "backlog",
    priority: "medium",
    points: 3,
  },
  {
    id: "LAB-21",
    title: "Экспорт заметок",
    status: "done",
    priority: "low",
    points: 2,
    cycleId: "08",
  },
];

export function useTrackerIssues({
  issues,
  defaultIssues = example,
  onIssuesChange,
}: TrackerProps) {
  const [local, setLocal] = useState(defaultIssues);
  const rows = issues ?? local;
  function commit(next: TrackerIssue[]) {
    if (issues === undefined) setLocal(next);
    onIssuesChange?.(next);
  }
  function update(id: string, patch: Partial<Omit<TrackerIssue, "id">>) {
    commit(
      rows.map((issue) => (issue.id === id ? { ...issue, ...patch } : issue)),
    );
  }
  return { rows, commit, update };
}

"use client";
import {
  Check,
  Circle,
  CircleCheck,
  CircleDot,
  SignalHigh,
  SignalLow,
  SignalMedium,
} from "lucide-react";
import { DropdownMenu } from "radix-ui";
import { Button } from "@/components/ui/button";

import {
  issueStatuses,
  issuePriorities,
  statusNames,
  priorityNames,
  type TrackerIssue,
  type IssueStatus,
  type IssuePriority,
} from "./tracker-issues";
export const statusIcons = {
  backlog: Circle,
  active: CircleDot,
  done: CircleCheck,
};
const priorityIcons = {
  high: SignalHigh,
  medium: SignalMedium,
  low: SignalLow,
};

export function IssueProperty({
  issue,
  field,
  onChange,
}: {
  issue: TrackerIssue;
} & (
  | { field: "status"; onChange: (value: IssueStatus) => void }
  | { field: "priority"; onChange: (value: IssuePriority) => void }
)) {
  const status = field === "status";
  const options = status ? issueStatuses : issuePriorities;
  const labels = { ...statusNames, ...priorityNames };
  const icons = { ...statusIcons, ...priorityIcons };
  const value = issue[field];
  const Icon = icons[value];
  return (
    <DropdownMenu.Root modal={false}>
      <DropdownMenu.Trigger asChild>
        <Button
          size="sm"
          variant="ghost"
          aria-label={[
            status ? "Статус" : "Приоритет",
            issue.id,
            labels[value],
          ].join(" · ")}
          className="h-8 max-w-full justify-start gap-1 rounded-md px-1.5 text-[11px] font-medium"
        >
          <Icon className="size-3.5 shrink-0 text-primary" />
          <span className="truncate">{labels[value]}</span>
        </Button>
      </DropdownMenu.Trigger>
      <DropdownMenu.Portal>
        <DropdownMenu.Content
          align="start"
          sideOffset={4}
          collisionPadding={8}
          className="z-50 min-w-36 rounded-xl border bg-popover p-1 text-popover-foreground shadow-md motion-safe:animate-in motion-safe:fade-in motion-safe:zoom-in-95"
        >
          <DropdownMenu.RadioGroup
            value={value}
            onValueChange={(next) => {
              if (status) onChange(next as IssueStatus);
              else onChange(next as IssuePriority);
            }}
          >
            {options.map((option) => {
              const Mark = icons[option];
              return (
                <DropdownMenu.RadioItem
                  key={option}
                  value={option}
                  className="flex min-h-9 cursor-pointer items-center gap-2 rounded-lg px-2 text-xs outline-none data-highlighted:bg-muted"
                >
                  <Mark size={14} />
                  {labels[option]}
                  <DropdownMenu.ItemIndicator className="ml-auto">
                    <Check size={13} />
                  </DropdownMenu.ItemIndicator>
                </DropdownMenu.RadioItem>
              );
            })}
          </DropdownMenu.RadioGroup>
        </DropdownMenu.Content>
      </DropdownMenu.Portal>
    </DropdownMenu.Root>
  );
}
